tool_input.command:
cd /home/kris/garden/scratch/project-wt-build-e-45496f58294c-97179fdd && python3 - <<'EOF'
p='packages/spaces-util/src/prompt-template-catalog.js'
s=open(p).read()
a=s.index("/**\n * Present a template as an inline command")
b=s.index("/**\n * The part of a mount the catalog reads.")
s=s[:a]+"""/**
 * How many form fields a template takes: one per `argument-hint` token, or one
 * per position up to the highest `$n` when the hint is shorter or absent.
 *
 * @param {PromptTemplate} template
 * @returns {number}
 */
export const countTemplateFields = ({ argumentHint, maxPosition }) =>
  Math.max(argumentHint.length, maxPosition);
harden(countTemplateFields);

/**
 * Present a template as an inline command with one field per position, named
 * `1`, `2`, ..., so the command form prompts for whatever the slash line left
 * out. `argument-hint` supplies the labels and which fields are required;
 * positions beyond the hint are labelled `$n` and optional.
 *
 * @param {PromptTemplate} template
 * @returns {CommandDefinition}
 */
const makeTemplateCommand = template => {
  const { name, description, argumentHint } = template;
  const hintText = argumentHint
    .map(({ label, required }) => (required ? `<${label}>` : `[${label}]`))
    .join(' ');
  return harden({
    name,
    label: name,
    description,
    ...(hintText ? { argumentHint: hintText } : {}),
    category: PROMPT_TEMPLATE_CATEGORY,
    mode: 'inline',
    submitLabel: 'Expand',
    fields: Array.from({ length: countTemplateFields(template) }, (_, index) => {
      const token = argumentHint[index];
      return {
        name: String(index + 1),
        label: token ? token.label : `$${index + 1}`,
        type: /** @type {const} */ ('text'),
        required: token ? token.required : false,
      };
    }),
  });
};

"""+s[b:]
open(p,'w').write(s)

p='packages/spaces-util/src/command-registry.js'
s=open(p).read()
s=s.replace(" * @property {string} [submitLabel] - Custom submit button label\n"," * @property {string} [submitLabel] - Custom submit button label\n * @property {string} [argumentHint] - Argument synopsis shown after the name in the menu\n",1)
open(p,'w').write(s)
p='packages/spaces-util/src/command-selector.js'
s=open(p).read()
s=s.replace("""    h('span', null, command.name),
    h('span', { class: 'command-desc' }""","""    h('span', null, command.name),
    command.argumentHint
      ? h('span', { class: 'command-argument-hint' }, ` ${command.argumentHint}`)
      : null,
    h('span', { class: 'command-desc' }""")
open(p,'w').write(s)
EOF
grep -n "^const h\|import.*h\b\|h = " packages/spaces-util/src/command-selector.js | head -3; grep -n "argumentHint" packages/spaces-util/src/command-registry.js
